        const number = String(value).replace('.', '\\.');
        return new RegExp('\\b' + label + '\\b\\W{0,20}' + number + '(?![\\d.])|(?<![\\d.])' + number + '\\W{0,20}(\\w+\\W+){0,2}' + label + '\\b', 'i').test(text);
