        const label = name.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase().replace(/[_-]+/g, ' ').trim().split(' ').map((word) => word.replace(/[.*+?^()|[\]\\{}$]/g, '\\$&')).join('\\W+');
